package com.bluelog;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BlueLogPluginTest {
	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws Exception {
		ExternalPluginManager.loadBuiltin(BlueLogPlugin.class);
		RuneLite.main(args);
	}
}

package com.bluelog;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.function.IntPredicate;
import org.junit.Test;

public class SectionHighlightTest {
	private static IntPredicate setOf(int... itemIds) {
		Set<Integer> ids = new HashSet<>();
		for (int itemId : itemIds) {
			ids.add(itemId);
		}

		return ids::contains;
	}

	private static final IntPredicate NOTHING = itemId -> false;

	@Test
	public void completedPageIsNotHighlighted() {
		assertFalse(BlueLogPlugin.onlyMissingIgnored(new int[] { 1, 2, 3 }, setOf(1, 2, 3), NOTHING));
	}

	@Test
	public void emptyPageIsNotHighlighted() {
		assertFalse(BlueLogPlugin.onlyMissingIgnored(new int[0], NOTHING, itemId -> true));
	}

	@Test
	public void pageMissingAnUnignoredItemIsNotHighlighted() {
		assertFalse(BlueLogPlugin.onlyMissingIgnored(new int[] { 1, 2, 3 }, setOf(1), setOf(2)));
	}

	@Test
	public void pageMissingOnlyIgnoredItemsIsHighlighted() {
		assertTrue(BlueLogPlugin.onlyMissingIgnored(new int[] { 1, 2, 3 }, setOf(1), setOf(2, 3)));
	}

	@Test
	public void pageWhereEveryItemIsMissingAndIgnoredIsHighlighted() {
		assertTrue(BlueLogPlugin.onlyMissingIgnored(new int[] { 1, 2 }, NOTHING, itemId -> true));
	}

	// The obtained set is keyed by the ids the server transmits, which for items holding data are
	// the replacements of the ids the pages list, so the cache has to hand over the replacements.
	@Test
	public void replacementIdIsWhatCountsAsObtained() {
		int flamtaerBagOnThePage = 12854;
		int flamtaerBagTransmitted = 25630;

		int[] remappedPage = { flamtaerBagTransmitted };
		assertFalse(BlueLogPlugin.onlyMissingIgnored(remappedPage, setOf(flamtaerBagTransmitted), NOTHING));

		int[] unremappedPage = { flamtaerBagOnThePage };
		assertTrue(Arrays.stream(unremappedPage).noneMatch(setOf(flamtaerBagTransmitted)::test));
	}
}

package com.bluelog;

import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.StructComposition;

@Slf4j
@Singleton
class CollectionLogCache {
	private static final int TOP_LEVEL_TABS_ENUM = 2102;
	private static final int TAB_PAGES_ENUM_PARAM = 683;
	private static final int PAGE_NAME_PARAM = 689;
	private static final int PAGE_ITEMS_ENUM_PARAM = 690;

	// Items that store data (satchels, bags, the Unsired) were given a second id to
	// fix a duping issue. The pages still list the original id while the server
	// transmits the replacement, so page ids have to be translated before they can
	// be compared against what was obtained.
	private static final int ITEM_REPLACEMENTS_ENUM = 3721;

	private final Client client;

	private Map<String, int[]> pagesByKey;

	@Inject
	private CollectionLogCache(Client client) {
		this.client = client;
	}

	void clear() {
		pagesByKey = null;
	}

	boolean isLoaded() {
		return pagesByKey != null && !pagesByKey.isEmpty();
	}

	Map<String, int[]> pages() {
		if (pagesByKey == null) {
			pagesByKey = readPages();
		}

		return pagesByKey;
	}

	int[] pageItemIds(String pageName) {
		return pages().get(BLUtils.normalizeString(pageName));
	}

	private Map<String, int[]> readPages() {
		Map<Integer, Integer> replacements = readReplacements();
		Map<String, int[]> pages = new LinkedHashMap<>();

		try {
			for (int tabStructId : client.getEnum(TOP_LEVEL_TABS_ENUM).getIntVals()) {
				int pagesEnumId = client.getStructComposition(tabStructId).getIntValue(TAB_PAGES_ENUM_PARAM);

				for (int pageStructId : client.getEnum(pagesEnumId).getIntVals()) {
					StructComposition page = client.getStructComposition(pageStructId);
					String pageName = page.getStringValue(PAGE_NAME_PARAM);
					if (pageName == null || pageName.isEmpty()) {
						continue;
					}

					int[] itemIds = client.getEnum(page.getIntValue(PAGE_ITEMS_ENUM_PARAM)).getIntVals().clone();
					for (int i = 0; i < itemIds.length; i++) {
						itemIds[i] = replacements.getOrDefault(itemIds[i], itemIds[i]);
					}

					pages.put(BLUtils.normalizeString(pageName), itemIds);
				}
			}
		} catch (RuntimeException e) {
			log.warn("Could not read the collection log pages from the game cache", e);
			return Collections.emptyMap();
		}

		log.debug("Read {} collection log pages from the game cache", pages.size());
		return pages;
	}

	private Map<Integer, Integer> readReplacements() {
		Map<Integer, Integer> replacements = new LinkedHashMap<>();

		try {
			EnumComposition enumComposition = client.getEnum(ITEM_REPLACEMENTS_ENUM);
			int[] keys = enumComposition.getKeys();
			int[] values = enumComposition.getIntVals();

			for (int i = 0; i < keys.length && i < values.length; i++) {
				replacements.put(keys[i], values[i]);
			}
		} catch (RuntimeException e) {
			log.warn("Could not read the collection log item replacements from the game cache", e);
		}

		return replacements;
	}
}

package com.bluelog;

import com.google.inject.Provides;
import java.awt.Color;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.IntPredicate;
import java.util.function.Predicate;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.ScriptID;
import net.runelite.api.events.MenuOpened;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.ExternalPluginsChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.Text;

@Slf4j
@PluginDescriptor(name = "BlueLog", description = "Colours a collection log section blue when the only items you are still missing are ones you have ignored, and marks those ignored items in the log", tags = {
		"collection", "log", "clog" })
public class BlueLogPlugin extends Plugin {
	private static final String ALL_PETS_PAGE_NAME = "All Pets";
	private static final String JAR_NAME_PREFIX = "jar of ";

	static final Color HIGHLIGHT_COLOUR = new Color(0x33, 0x99, 0xFF);

	private static final int COMPLETED_PAGE_COLOUR = 0x0dc10d;
	private static final int RGB_MASK = 0xFFFFFF;
	private static final int COLLECTION_LOG_GROUP_ID = InterfaceID.Collection.LIST >>> 16;

	private static final int[] SECTION_LIST_WIDGET_IDS = {
			InterfaceID.Collection.BOSS_TEXT,
			InterfaceID.Collection.RAID_TEXT,
			InterfaceID.Collection.CLUE_TEXT,
			InterfaceID.Collection.MINIGAME_TEXT,
			InterfaceID.Collection.OTHER_TEXT,
	};

	private static final class Recolouring {
		private final int original;
		private final int applied;

		private Recolouring(int original, int applied) {
			this.original = original;
			this.applied = applied;
		}
	}

	private static int rgb(int colour) {
		return colour & RGB_MASK;
	}

	private static int rgb(Color colour) {
		return colour.getRGB() & RGB_MASK;
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private EventBus eventBus;

	@Inject
	private CollectionLogCache collectionLogCache;

	@Inject
	private BlueLogConfig config;

	@Inject
	private ItemManager itemManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private BlueLogOverlay overlay;

	@Inject
	private ObtainedItems obtainedItems;

	private final Map<String, Recolouring> recolourings = new HashMap<>();

	private Predicate<String> isIgnored = name -> false;

	private Set<String> petNames;

	boolean didPetNamesLoad() {
		return petNames != null && !petNames.isEmpty();
	}

	@Provides
	BlueLogConfig provideConfig(ConfigManager configManager) {
		return configManager.getConfig(BlueLogConfig.class);
	}

	private void rebuildIgnoredItemTest() {
		Set<String> ignoredNames = new LinkedHashSet<>(BLUtils.textToItemNamesSet(config.ignoredItems()));

		if (config.ignoreAllPets() && didPetNamesLoad()) {
			ignoredNames.addAll(petNames);
		}

		boolean ignoreAllJars = config.ignoreAllJars();
		isIgnored = name -> ignoredNames.contains(name)
				|| (ignoreAllJars && name.startsWith(JAR_NAME_PREFIX));
	}

	private void loadPetNames() {
		int[] petItemIds = collectionLogCache.pageItemIds(ALL_PETS_PAGE_NAME);

		if (petItemIds == null) {
			log.warn("Could not load pet names from the game cache");
			return;
		}

		Set<String> petNamesLocal = new LinkedHashSet<>();
		for (int petItemId : petItemIds) {
			String petName = getItemIdName(petItemId);
			if (petName != null && !petName.isEmpty()) {
				petNamesLocal.add(BLUtils.normalizeString(petName));
			} else {
				log.warn("Could not load pet name for item ID {}", petItemId);
			}
		}

		if (!petNamesLocal.isEmpty()) {
			petNames = petNamesLocal;
		} else {
			log.warn("No pet names were loaded from the game cache");
		}
	}

	private static Widget[] sectionEntries(Widget sectionList) {
		Widget[] children = sectionList.getDynamicChildren();
		if (children != null && children.length > 0) {
			return children;
		}

		return new Widget[] { sectionList };
	}

	private Integer desiredColour(String sectionName) {
		if (!obtainedItems.isLoaded()) {
			return null;
		}

		int[] itemIds = collectionLogCache.pageItemIds(sectionName);
		if (itemIds == null || itemIds.length == 0) {
			return null;
		}

		return onlyMissingIgnored(itemIds, obtainedItems::contains, this::isItemIdIgnored)
				? rgb(HIGHLIGHT_COLOUR)
				: null;
	}

	static boolean onlyMissingIgnored(int[] itemIds, IntPredicate obtained, IntPredicate ignored) {
		boolean anyMissing = false;

		for (int itemId : itemIds) {
			if (obtained.test(itemId)) {
				continue;
			}

			anyMissing = true;
			if (!ignored.test(itemId)) {
				return false;
			}
		}

		return anyMissing;
	}

	private void recolourSectionLists() {
		for (int sectionListWidgetId : SECTION_LIST_WIDGET_IDS) {
			Widget sectionList = client.getWidget(sectionListWidgetId);
			if (sectionList == null) {
				continue;
			}

			for (Widget sectionEntry : sectionEntries(sectionList)) {
				String sectionName = Text.removeTags(Text.sanitize(sectionEntry.getText())).trim();
				if (sectionName.isEmpty()) {
					continue;
				}

				recolourSectionEntry(sectionEntry, sectionName);
			}
		}
	}

	private void recolourSectionEntry(Widget sectionEntry, String sectionName) {
		String key = BLUtils.normalizeString(sectionName);
		int currentColour = rgb(sectionEntry.getTextColor());
		Recolouring recolouring = recolourings.get(key);

		if (recolouring != null && currentColour != recolouring.applied) {
			recolourings.remove(key);
			recolouring = null;
		}

		if (currentColour == COMPLETED_PAGE_COLOUR) {
			return;
		}

		Integer desired = desiredColour(sectionName);

		if (desired == null) {
			if (recolouring != null) {
				sectionEntry.setTextColor(recolouring.original);
				recolourings.remove(key);
			}
			return;
		}

		int original = recolouring == null ? currentColour : recolouring.original;
		sectionEntry.setTextColor(desired);
		recolourings.put(key, new Recolouring(original, desired));
	}

	private static boolean isCollectionLogSlot(Widget slot) {
		return slot.getId() == InterfaceID.Collection.ITEMS_CONTENTS
				|| slot.getParentId() == InterfaceID.Collection.ITEMS_CONTENTS;
	}

	private void addIgnoreMenuEntry(int itemId) {
		String itemName = getItemIdName(itemId);
		boolean alreadyIgnored = BLUtils.textToItemNamesSet(config.ignoredItems())
				.contains(BLUtils.normalizeString(itemName));

		// Ignoring an item you already have changes nothing, so the option is only
		// worth showing on an obtained item to undo an ignore made before you got it.
		if (obtainedItems.contains(itemId) && !alreadyIgnored) {
			return;
		}

		client.getMenu()
				.createMenuEntry(-1)
				.setOption(alreadyIgnored ? "Unignore item" : "Ignore item")
				.setTarget("<col=ff9040>" + itemName + "</col>")
				.setType(MenuAction.RUNELITE)
				.onClick(e -> toggleIgnoredItemInConfig(itemName));
	}

	private void toggleIgnoredItemInConfig(String itemName) {
		List<String> ignoredItems = new ArrayList<>(BLUtils.textToItemNames(config.ignoredItems()));

		String normalisedTarget = BLUtils.normalizeString(itemName);
		if (!ignoredItems.removeIf(existing -> BLUtils.normalizeString(existing).equals(normalisedTarget))) {
			ignoredItems.add(itemName);
		}

		configManager.setConfiguration(BlueLogConfig.GROUP, BlueLogConfig.IGNORED_ITEMS_KEY, Text.toCSV(ignoredItems));
		eventBus.post(new ExternalPluginsChanged());
	}

	private boolean isItemIgnored(String itemName) {
		return isIgnored.test(BLUtils.normalizeString(itemName));
	}

	private String getItemIdName(int itemId) {
		return BLUtils.stripMembersSuffix(itemManager.getItemComposition(itemId).getName());
	}

	boolean isItemIdIgnored(int itemId) {
		return isItemIgnored(getItemIdName(itemId));
	}

	@Override
	protected void startUp() {
		overlayManager.add(overlay);
		obtainedItems.startUp(this::recolourSectionLists);
		clientThread.invokeLater(this::rebuildIgnoredItemTest);
	}

	@Override
	protected void shutDown() {
		obtainedItems.shutDown();
		overlayManager.remove(overlay);
		isIgnored = name -> false;
		petNames = null;
		recolourings.clear();
		collectionLogCache.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event) {
		if (!BlueLogConfig.GROUP.equals(event.getGroup())) {
			return;
		}

		clientThread.invokeLater(() -> {
			rebuildIgnoredItemTest();
			recolourSectionLists();
		});
	}

	@Subscribe
	public void onMenuOpened(MenuOpened event) {
		for (MenuEntry entry : event.getMenuEntries()) {
			Widget slot = entry.getWidget();
			if (slot == null || !isCollectionLogSlot(slot) || slot.getItemId() <= 0) {
				continue;
			}

			addIgnoreMenuEntry(slot.getItemId());
			return;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() != ScriptID.COLLECTION_DRAW_LIST) {
			return;
		}

		if (!didPetNamesLoad()) {
			loadPetNames();
			rebuildIgnoredItemTest();
		}

		recolourSectionLists();
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event) {
		obtainedItems.load();
		clientThread.invokeLater(this::recolourSectionLists);
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event) {
		if (event.getGroupId() == COLLECTION_LOG_GROUP_ID) {
			recolourings.clear();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event) {
		if (event.getGroupId() == COLLECTION_LOG_GROUP_ID) {
			clientThread.invokeLater(this::recolourSectionLists);
		}
	}
}

package com.bluelog;

import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

import net.runelite.client.util.Text;

public class BLUtils {
  private static final String MEMBERS_SUFFIX = "(members)";

  public static String normalizeString(String string) {
    return string.toLowerCase(Locale.ROOT).trim();
  }

  // Free worlds append this to members only item names.
  public static String stripMembersSuffix(String itemName) {
    String trimmed = itemName.trim();
    if (!normalizeString(trimmed).endsWith(MEMBERS_SUFFIX)) {
      return trimmed;
    }

    return trimmed.substring(0, trimmed.length() - MEMBERS_SUFFIX.length()).trim();
  }

  public static List<String> textToItemNames(String configuredText) {
    if (configuredText == null || configuredText.trim().isEmpty()) {
      return Collections.emptyList();
    }

    List<String> items = new ArrayList<>();
    for (String part : Text.fromCSV(configuredText)) {
      String cleaned = Text.removeTags(part).trim();
      if (!cleaned.isEmpty()) {
        items.add(cleaned);
      }
    }

    return items;
  }

  public static Set<String> textToItemNamesSet(String configuredText) {
    Set<String> normalisedItems = new LinkedHashSet<>();
    for (String item : textToItemNames(configuredText)) {
      normalisedItems.add(normalizeString(item));
    }

    return normalisedItems;
  }
}

package com.bluelog;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BlueLogConfig.GROUP)
public interface BlueLogConfig extends Config {
	String GROUP = "bluelog";
	String IGNORED_ITEMS_KEY = "ignoredItems";

	@ConfigSection(name = "Items", description = "Items you do not care about", position = 0)
	String itemsSection = "itemsSection";

	@ConfigItem(keyName = IGNORED_ITEMS_KEY, name = "Ignored items", description = "List of ignored items, separated by commas", position = 1, section = itemsSection)
	default String ignoredItems() {
		return "";
	}

	@ConfigItem(keyName = "ignoreAllPets", name = "Ignore all pets", description = "Ignores pets from all sections", position = 2, section = itemsSection)
	default boolean ignoreAllPets() {
		return true;
	}

	@ConfigItem(keyName = "ignoreAllJars", name = "Ignore all jars", description = "Ignores jars from all sections", position = 3, section = itemsSection)
	default boolean ignoreAllJars() {
		return true;
	}

	@ConfigItem(keyName = "markerCorner", name = "Marker corner", description = "Corner of the item the ignored marker is drawn in", position = 4, section = itemsSection)
	default MarkerCorner markerCorner() {
		return MarkerCorner.TOP_RIGHT;
	}
}

package com.bluelog;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

class BlueLogOverlay extends Overlay {
	private static final int MARKER_SIZE = 7;

	private final Client client;
	private final BlueLogPlugin plugin;
	private final BlueLogConfig config;

	@Inject
	private BlueLogOverlay(Client client, BlueLogPlugin plugin, BlueLogConfig config) {
		this.client = client;
		this.plugin = plugin;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics) {
		Widget itemsContents = client.getWidget(InterfaceID.Collection.ITEMS_CONTENTS);
		if (itemsContents == null || itemsContents.isHidden()) {
			return null;
		}

		Widget[] slots = itemsContents.getDynamicChildren();
		if (slots == null || slots.length == 0) {
			return null;
		}

		MarkerCorner corner = config.markerCorner();
		Shape originalClip = graphics.getClip();

		graphics.setClip(itemsContents.getBounds());
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

		for (Widget slot : slots) {
			if (slot.isHidden() || slot.getItemId() <= 0 || slot.getOpacity() == 0) {
				continue;
			}

			if (!plugin.isItemIdIgnored(slot.getItemId())) {
				continue;
			}

			Rectangle bounds = slot.getBounds();
			boolean right = corner == MarkerCorner.TOP_RIGHT || corner == MarkerCorner.BOTTOM_RIGHT;
			boolean bottom = corner == MarkerCorner.BOTTOM_LEFT || corner == MarkerCorner.BOTTOM_RIGHT;
			int x = right ? bounds.x + bounds.width - MARKER_SIZE : bounds.x;
			int y = bottom ? bounds.y + bounds.height - MARKER_SIZE : bounds.y;

			// black border
			graphics.setColor(Color.BLACK);
			graphics.fillOval(x, y, MARKER_SIZE, MARKER_SIZE);

			// coloured interior
			graphics.setColor(BlueLogPlugin.HIGHLIGHT_COLOUR);
			graphics.fillOval(x + 1, y + 1, MARKER_SIZE - 2, MARKER_SIZE - 2);
		}

		graphics.setClip(originalClip);
		return null;
	}
}

package com.bluelog;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.MenuAction;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;

// The core idea used below comes from WikiSync and RuneProfile: trigger a collection log search 
// operation to make the server send the whole log, reading the item id and quantity from the 
// arguments of script 4100, and treating the stream as finished once a couple of ticks pass.

// This plugin waits a few ticks before creating its own search op so as to avoid sending a 
// duplicate request if another plugin has already done so. 
@Slf4j
@Singleton
class ObtainedItems {
	private static final int COLLECTION_DELAYED_TRANSMIT = 4100;
	private static final int COLLECTION_LOG_SETUP = 7797;
	private static final int COLLECTION_INIT = 2240;

	private static final int TICKS_TO_LET_OTHERS_REQUEST = 3;
	private static final int TICKS_AFTER_LAST_TRANSMIT = 2;
	private static final int TICKS_BEFORE_GIVING_UP = 10;

	private static final String OBTAINED_ITEMS_KEY = "obtainedItems";

	private final Client client;
	private final EventBus eventBus;
	private final ConfigManager configManager;

	private final Set<Integer> obtained = new HashSet<>();
	private final Set<Integer> arriving = new HashSet<>();

	private Runnable onUpdated = () -> {
	};

	private boolean loaded;
	private int openTick = -1;
	private int requestTick = -1;
	private int lastTransmitTick = -1;

	@Inject
	private ObtainedItems(Client client, EventBus eventBus, ConfigManager configManager) {
		this.client = client;
		this.eventBus = eventBus;
		this.configManager = configManager;
	}

	void startUp(Runnable onUpdated) {
		this.onUpdated = onUpdated;
		eventBus.register(this);
		load();
	}

	void shutDown() {
		eventBus.unregister(this);
		clear();
	}

	void clear() {
		obtained.clear();
		loaded = false;
		resetCollection();
	}

	boolean isLoaded() {
		return loaded;
	}

	boolean contains(int itemId) {
		return obtained.contains(itemId);
	}

	private void resetCollection() {
		arriving.clear();
		openTick = -1;
		requestTick = -1;
		lastTransmitTick = -1;
	}

	private boolean isOpenedFromAdventureLog() {
		return client.getVarbitValue(VarbitID.COLLECTION_POH_HOST_BOOK_OPEN) == 1;
	}

	private int obtainedSlotCount() {
		return client.getVarpValue(VarPlayerID.COLLECTION_COUNT);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event) {
		switch (event.getGameState()) {
			case HOPPING:
			case LOGGING_IN:
			case CONNECTION_LOST:
				resetCollection();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event) {
		if (event.getScriptId() != COLLECTION_LOG_SETUP) {
			return;
		}

		if (isOpenedFromAdventureLog()) {
			resetCollection();
			return;
		}

		if (openTick != -1) {
			return;
		}

		resetCollection();
		openTick = client.getTickCount();
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event) {
		if (event.getScriptId() != COLLECTION_DELAYED_TRANSMIT || isOpenedFromAdventureLog()) {
			return;
		}

		Object[] args = event.getScriptEvent().getArguments();
		int itemId = (int) args[1];
		int quantity = (int) args[2];

		lastTransmitTick = client.getTickCount();

		if (quantity > 0) {
			arriving.add(itemId);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event) {
		int tick = client.getTickCount();

		if (lastTransmitTick != -1) {
			if (tick > lastTransmitTick + TICKS_AFTER_LAST_TRANSMIT) {
				onTransmitsSettled();
			}
			return;
		}

		if (requestTick != -1) {
			if (tick > requestTick + TICKS_BEFORE_GIVING_UP) {
				log.debug("Nothing was transmitted within {} ticks of asking for the collection log",
						TICKS_BEFORE_GIVING_UP);
				resetCollection();
			}
			return;
		}

		if (openTick != -1 && tick > openTick + TICKS_TO_LET_OTHERS_REQUEST) {
			request();
		}
	}

	private void request() {
		requestTick = client.getTickCount();

		if (openTick == -1) {
			openTick = requestTick;
		}
		client.menuAction(-1, InterfaceID.Collection.SEARCH_TOGGLE, MenuAction.CC_OP, 1, -1, "Search", null);
		client.runScript(COLLECTION_INIT);
	}

	private void onTransmitsSettled() {
		int expected = obtainedSlotCount();

		if (arriving.size() < expected && requestTick == -1) {
			log.debug("Only {} of {} slots arrived, so that was a page load; asking for the whole log",
					arriving.size(), expected);
			arriving.clear();
			lastTransmitTick = -1;
			request();
			return;
		}

		obtained.clear();
		obtained.addAll(arriving);
		loaded = true;
		log.debug("Collected {} obtained collection log items", obtained.size());

		store();
		resetCollection();
		onUpdated.run();
	}

	// Kept per character so the log is already coloured the moment it opens, rather
	// than several seconds later when the transmits land. A fresh collection
	// overwrites it every time.
	void load() {
		obtained.clear();
		loaded = false;
		resetCollection();

		String stored = configManager.getRSProfileConfiguration(BlueLogConfig.GROUP, OBTAINED_ITEMS_KEY);
		if (stored == null || stored.isEmpty()) {
			return;
		}

		for (String itemId : stored.split(",")) {
			try {
				obtained.add(Integer.parseInt(itemId.trim()));
			} catch (NumberFormatException e) {
				log.warn("Discarding an unreadable stored collection log");
				obtained.clear();
				return;
			}
		}

		loaded = !obtained.isEmpty();
		log.debug("Loaded {} obtained collection log items for this character", obtained.size());
	}

	private void store() {
		List<Integer> sorted = new ArrayList<>(obtained);
		sorted.sort(null);

		StringBuilder sb = new StringBuilder();
		for (Integer itemId : sorted) {
			if (sb.length() > 0) {
				sb.append(',');
			}
			sb.append(itemId);
		}

		String csv = sb.toString();
		if (!csv.equals(configManager.getRSProfileConfiguration(BlueLogConfig.GROUP, OBTAINED_ITEMS_KEY))) {
			configManager.setRSProfileConfiguration(BlueLogConfig.GROUP, OBTAINED_ITEMS_KEY, csv);
		}
	}
}

